package com.ruoyi.ai.mapper;import java.util.*;import org.apache.ibatis.annotations.*;public interface AiConversationAuditMapper{@Select({"<script>","select c.conversation_id as conversationId,c.user_id as userId,u.user_name as userName,c.title,c.model_id as modelId,m.model_code as modelCode,c.reasoning_effort as reasoningEffort,c.route,c.status,c.create_time as createTime,c.update_time as updateTime,","exists(select 1 from ai_message am where am.conversation_id=c.conversation_id and am.role='TOOL') as hasTool,","exists(select 1 from ai_pending_tool_call pt where pt.conversation_id=c.conversation_id and pt.risk_level in ('WRITE','DANGEROUS_WRITE')) as hasWrite,","exists(select 1 from ai_run ar where ar.conversation_id=c.conversation_id and ar.cancel_reason in ('USER_STOP','DOUBLE_ESC','USER_LOGOUT','CLIENT_RELOAD')) as hasStop,","exists(select 1 from ai_run ar where ar.conversation_id=c.conversation_id and ar.cancel_reason='STEERING') as hasSteering,","exists(select 1 from ai_checkpoint cp where cp.conversation_id=c.conversation_id) as hasCompaction ","from ai_conversation c left join sys_user u on u.user_id=c.user_id left join ai_model m on m.model_id=c.model_id where 1=1 ","<if test='userId != null'>and c.user_id=#{userId} </if>","<if test='conversationId != null'>and c.conversation_id=#{conversationId} </if>","<if test='modelId != null'>and c.model_id=#{modelId} </if>","<if test='status != null and status != \"\"'>and c.status=#{status} </if>","<if test='title != null and title != \"\"'>and c.title like concat('%',#{title},'%') </if>","<if test='beginTime != null and beginTime != \"\"'>and c.update_time &gt;= #{beginTime} </if>","<if test='endTime != null and endTime != \"\"'>and c.update_time &lt;= #{endTime} </if>","order by c.update_time desc limit 200","</script>"})List<Map<String,Object>> list(@Param("userId")Long userId,@Param("conversationId")Long conversationId,@Param("modelId")Long modelId,@Param("status")String status,@Param("title")String title,@Param("beginTime")String beginTime,@Param("endTime")String endTime);}
